Ltac cl_blob112 S1L :=
  lazymatch type of S1L with rw_cells _ _ ?spa [?c0; ?c1; ?c2; ?c3; ?c4; ?c5; ?c6; ?c7] =>
    let CC := fresh "CC" in
    split_frameA S1L [c0; c1; c2; c3; c4; c5; c6] [c7] S1L CC; blob_at spa;
    lazymatch goal with BL : rw_cells _ _ spa [CB _ _] |- _ => join_frameA BL CC spa; rename BL into S1L end
  end.

(* [comment removed for export] *)
Ltac cl_shapeF S1L OPT :=
  cl_blob112 S1L;
  let jo := fresh "jo" in let OPTb := fresh "OPTb" in
  destruct (rw_cells_forget _ _ _ _ OPT) as [jo OPTb]; clear OPT; cbn [cells_size csize Nat.add OptItCells] in OPTb;
  try (match goal with SZ : cells_size _ = _ |- _ => rewrite SZ in OPTb; cbn [Nat.add] in OPTb end);
  lazymatch type of S1L with rw_cells _ _ ?spa _ => join_frameA S1L OPTb spa end.

