Definition cl_lctx {HCEIL : HeapCeil} (H : asr) (LF : list fframe) (m m1 : mem) (sp : word) (spa : Z) (gsz : nat) (gj : list byte)
    (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word)
    (P E vp : Z) (vbs : list byte) (c1 : pcore) (pad7 pad2 : list byte) (E0 : ecv) (g : bool) (lo shi ff fp : Z) (h0 h1 h2 h3 : word)
    (j0 : list byte) (xv has : Z) (tu : word) (j64 j160 : list byte) (optc : list cell) : Prop :=
  dof_ctx H LF m m1 sp spa gsz gj rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v P E vp vbs c1 pad7 pad2 (ErrCodeCells E0) g lo shi ff fp h0 h1 h2 h3 DOF_SHB
  /\ rw_cells asegs m1 spa [CB 24 j0; C8 (wz (Z.shiftr (P + 76) 3 + 2147450880)); C8 (wz xv); C8 (wz has); C8 tu; C8 (wz E); CB 48 j64; C8 (wz E)]
  /\ rw_cells asegs m1 (spa + 120) optc
  /\ rw_cells asegs m1 (spa + 160) [CB 24 j160]
  /\ rw_cells asegs m1 (ff + 64) [C8 (wz vp); C8 (wz (Z.of_nat (length vbs)))].

Lemma shB_B16 : firstn 2 (skipn 8 DOF_SHB) = repeat (b8 0) 2.  Proof. reflexivity. Qed.

