Lemma cl_all : forall n, CL_AT (Z.of_nat n).
Proof.
  induction n as [|n IH].
  - intros itc vq vl err pad7o xv has tu. intros until h3. intros L PURE DC XV HS Q1 Q2 Q3 Q4 QM ERR. exfalso. cbn [Z.of_nat] in QM. clear - Q1 Q2 Q3 Q4 QM. lia.
  - rewrite Nat2Z.inj_succ. replace (Z.succ (Z.of_nat n)) with (Z.of_nat n + 1) by lia. apply cl_step. exact IH.
Qed.

End CL.
